import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();
        List<Integer> digits = new ArrayList<>();
        while (n > 0) {
            digits.add((int)(n % k));
            n /= k;
        }
        int size = digits.size();

        long MOD = 1000000007;

        long[][] matrix = new long[k + 1][k + 1];
        for (int j = 0; j <= k; j++) {
            matrix[0][j] = 1;
            matrix[j][j] = 1;
        }

        List<long[][]> powerMatrices = new ArrayList<>();
        powerMatrices.add(matrix);

        for (int i = 1; i < size; i++) {
            long[][] prev = powerMatrices.get(i - 1);
            long[][] now = new long[k + 1][k + 1];
            for (int x = 0; x <= k; x++) {
                for (int y = 0; y <= k; y++) {
                    for (int z = 0; z <= k; z++) {
                        now[x][z] = (now[x][z] + prev[x][y] * matrix[y][z]) % MOD;
                    }
                }
            }
            powerMatrices.add(now);
        }

        long result = 1;
        int add = 0;
        for (int i = size - 1; i >= 0; i--) {
            int digit = digits.get(i);
            for (int j = 0; j < digit; j++) {
                long[][] currentMatrix = powerMatrices.get(i);
                for (int x = 0; x <= k; x++) {
                    result = (result * currentMatrix[(x + add) % k][k]) % MOD;
                }
                add = (add + j) % k;
            }
        }
        System.out.println(result % MOD);
        sc.close();
    }
}
